beforeExample:
class MyClass {
    public String format(int size) {
        return java.text.MessageFormat.format("Count: {0}", new java.lang.Integer(size));
    }
}

afterExample:
class MyClass {
    public String format(int size) {
        return java.text.MessageFormat.format("Count: {0}", java.lang.Integer.valueOf(size));
    }
}

